	"face_liveness_introduction_disclaimer": "Ứng dụng sẽ nhanh chóng chụp và gửi một bức ảnh đến AWS, chỉ nhằm xác nhận rằng bạn là người thật, không phải bot. Ảnh này không bao giờ được gửi đến X và sẽ được AWS xóa ngay sau khi hoàn tất quá trình xác minh. Ảnh không được sử dụng cho bất kỳ mục đích nào khác ngoài các biện pháp chống bot, đồng thời sẽ không được bán, cho thuê hoặc trao đổi.",
