	"gift_premium_terms_footer": "Giá của gói thuê bao quà tặng được tính tại thời điểm mua và không được hoàn lại. Đây là gói sử dụng một lần, không thể thay thế, không thể kết hợp và không có giá trị quy đổi thành tiền mặt. Gói sẽ bắt đầu có hiệu lực sau khi X xét duyệt và chuyển giao cho người nhận. Người nhận phải chấp thuận %1$s cũng như các chính sách của chúng tôi. Nếu người nhận không đáp ứng được yêu cầu về điều kiện, hủy gói thuê bao hoặc từ chối chấp thuận điều khoản và chính sách của chúng tôi, thì gói thuê bao quà tặng này sẽ không được hoàn lại hay quy đổi. Có thể áp dụng thuế. Điều khoản có thể thay đổi. %2$s.",
