	"go_to_settings_button_text": "Đến cài đặt",
	"go_to_twitter": "Chuyển đến x.com",
	"golive__tip_broadcaster_1": "<b>MẸO:</b> Cảm ơn vì đã phát trực tuyến! Chào đón mọi người bằng cách nói \\\"xin chào\\\" với họ khi họ tham gia video trực tuyến của bạn.",
	"golive__tip_broadcaster_10": "<b>MẸO:</b> Cảm ơn bạn vì đã phát trực tuyến trên X! <3",
	"golive__tip_broadcaster_2": "<b>MẸO:</b> Thử nhắc tới mọi người bằng tên khi họ tham gia video trực tuyến của bạn — họ sẽ giật mình đấy!",
	"golive__tip_broadcaster_3": "<b>MẸO:</b> Hãy đảm bảo phát trực tuyến ít nhất vài phút để mọi người tìm bạn dễ dàng hơn.",
	"golive__tip_broadcaster_4": "<b>MẸO:</b> Hỏi những người xem của bạn họ đến từ đâu — đây là một cách hay để phá vỡ sự im lặng.",
	"golive__tip_broadcaster_5": "<b>MẸO:</b> Cảm ơn những người đã điều chỉnh và phản hồi lại bình luận của họ để khiến họ tiếp tục xem.",
	"golive__tip_broadcaster_6": "<b>MẸO:</b> Nếu bạn mất kết nối khi đang phát trực tuyến, hãy đi đến chỗ có tín hiệu tốt hơn.",
	"golive__tip_broadcaster_7": "<b>MẸO:</b> Đề nghị mọi người theo dõi bạn để họ có thể được thông báo lần tiếp theo bạn phát trực tuyến.",
	"golive__tip_broadcaster_8": "<b>MẸO:</b> Bắt đầu video trực tuyến của bạn bằng cách nói \\\"xin chào\\\" ngay lập tức. Những người đang xem khi đó sẽ yêu thích điều này.",
	"golive__tip_broadcaster_9": "<b>MẸO:</b> Cảm ơn mọi người vì đã xem trước khi bạn kết thúc video trực tuyến của mình.",
	"golive__tip_pre_broadcast_1": "<b>MẸO:</b> Viết một tiêu đề trước khi bạn phát trực tuyến để giúp mọi người tìm thấy video của bạn.",
	"golive__tip_pre_broadcast_2": "<b>MẸO:</b> Một tiêu đề mô tả sẽ giúp mọi người hiểu rõ hơn video trực tuyến của bạn nói về điều gì.",
	"golive__tip_pre_broadcast_3": "<b>MẸO:</b> Bạn cần ý tưởng? Hãy dạo một vòng, chia sẻ tài năng, hoặc nói chuyện về những điều làm bạn thấy hứng thú.",
	"golive__tip_pre_broadcast_4": "<b>MẸO:</b> Hãy chắc chắn bạn có tín hiệu điện thoại mạnh trước khi phát trực tuyến.",
	"golive__tip_pre_broadcast_5": "<b>MẸO:</b> Thêm biểu tượng đánh dấu vào tiêu đề của bạn để giúp mọi người tìm thấy video trực tuyến của bạn.",
	"golive__tip_pre_broadcast_6": "<b>MẸO:</b> Đó là tất cả những mẹo mà chúng tôi hiện có — cảm ơn bạn vì đã phát trực tuyến trên X!",
	"google_disclaimer": "Thông tin địa chỉ được chia sẻ với Google. Xem {{}}Điều khoản dịch vụ{{}} của Google Maps và {{}}Chính sách riêng tư của Google{{}} để tìm hiểu thêm.",
