	"identity_description": "Xác nhận giấy tờ tùy thân do chính phủ cấp để xác nhận danh tính và mở khóa các tính năng khi là người đăng ký gói Premium.",
	"identity_education_camera_permissions": "Để xác nhận danh tính của bạn, chúng tôi cần truy cập camera của bạn.",
	"identity_education_cancel": "Tạm bỏ qua",
	"identity_education_conditions": "Tôi đồng ý cho X và Au10tix sử dụng hình ảnh giấy tờ tùy thân và ảnh tự sướng của tôi (bao gồm cả dữ liệu sinh trắc đã trích xuất) để xác định danh tính của tôi và để phục vụ các mục đích về an toàn và bảo mật có liên quan của X, trong đó có ngăn chặn hành vi mạo danh. Au10tix có thể lưu dữ liệu này tối đa 30 ngày. {{}}Tìm hiểu thêm{{}}",
	"identity_education_conditions_age_verification": "Tôi đồng ý cho X và Persona sử dụng hình ảnh giấy tờ tùy thân và ảnh của tôi để xác nhận tuổi. Ảnh của bạn sẽ không được lưu trữ. X và xAI có thể giữ lại thông tin về tuổi của bạn.{{}}Tìm hiểu thêm{{}}",
	"identity_education_conditions_eea": "\"Tôi đồng ý cho X chia sẻ hình ảnh giấy tờ tùy thân của mình, bao gồm dữ liệu sinh trắc và dữ liệu cá nhân từ hồ sơ của tôi với Au10tix để phục vụ mục đích xác nhận danh tính của tôi.\nTôi cũng đồng ý cho X lưu trữ hình ảnh giấy tờ tùy thân của mình, bao gồm dữ liệu sinh trắc, trong khoảng thời gian tối đa 30 ngày và dùng hình ảnh này cùng dữ liệu từ hồ sơ của tôi để phục vụ mục đích giữ an toàn và bảo mật, bao gồm cả việc ngăn chặn mạo danh. {{}}Tìm hiểu thêm{{}}\"",
	"identity_education_conditions_persona_vendor": "Tôi đồng ý cho X và Persona sử dụng hình ảnh giấy tờ tùy thân và ảnh selfie của tôi (trong đó có cả dữ liệu sinh trắc học đã được trích xuất) để xác nhận danh tính của tôi và để phục vụ các mục đích khác của X có liên quan đến vấn đề an toàn và bảo mật, ngăn chặn lừa đảo và thanh toán. Persona có thể lưu trữ dữ liệu trên trong tối đa 30 ngày. X có thể lưu trữ tên đầy đủ, địa chỉ và giá trị băm của mã số giấy tờ tùy thân của tôi trong thời gian tôi đăng ký dịch vụ X Premium.{{}}Tìm hiểu thêm{{}}",
