	"payment_funds_insurance_footer_text": "Tiền gửi của bạn được lưu ký tại Ngân hàng Cross River, Thành viên FDIC và được FDIC bảo hiểm lên đến 250.000 USD cho mỗi cá nhân và pháp nhân, đối với tất cả các tài khoản thuộc từng danh mục sở hữu tài khoản tại ngân hàng (tính gộp), bao gồm cả các tài khoản được nắm giữ với tư cách đại diện.",
	"payment_funds_insurance_footer_text_format": "Tiền gửi của bạn được lưu ký tại Ngân hàng Cross River (\\\"Ngân hàng\\\"), Thành viên FDIC và được FDIC bảo hiểm lên đến {amount} cho mỗi cá nhân và pháp nhân, đối với tất cả các tài khoản thuộc từng danh mục sở hữu tài khoản tại Ngân hàng (tính gộp), bao gồm cả các tài khoản được nắm giữ với tư cách đại diện.",
	"payment_funds_insurance_sweep_disclaimer": "Tiền gửi sẽ được lưu ký tại Ngân hàng Cross River, Thành viên của FDIC và tại ﻿các tổ chức khác được FDIC bảo hiểm﻿. Phải đáp ứng ﻿một số điều kiện nhất định﻿ để được áp dụng bảo hiểm tiền gửi gián tiếp. X Payments LLC không phải là ngân hàng được FDIC bảo hiểm. Bảo hiểm tiền gửi chỉ chi trả khi ngân hàng được bảo hiểm phá sản.",
	"payment_funds_insurance_sweep_presentation": "Tiền gửi của bạn sẽ tự động được đăng ký vào Chương trình X Cash Sweep. Với chương trình này, bạn có thể tiếp cận bảo hiểm FDIC lên đến $10 triệu, tùy thuộc vào một số giới hạn nhất định. ﻿Tìm hiểu thêm﻿.",
