	"ps__time_unit_seconds": "giây",
	"ps__tip_broadcaster_1": "<b>MẸO:</b> Cảm ơn vì đã phát! Hãy chắc chắn nói xin chào với mọi người khi họ tham gia.",
	"ps__tip_broadcaster_11": "<b>MẸO:</b> Cảm ơn vì đã phát trên Periscope!",
	"ps__tip_broadcaster_2": "<b>MẸO:</b> Thử gọi tên người xem tham gia; họ sẽ giật mình đấy!",
	"ps__tip_broadcaster_3": "<b>MẸO:</b> Hãy chắc chắn phát ít nhất một vài phút để mọi người tìm thấy bạn dễ dàng hơn.",
	"ps__tip_broadcaster_4": "<b>MẸO:</b> Hỏi những người xem của bạn xem họ đến từ đâu là một cách tuyệt vời để phá tan sự im lặng.",
	"ps__tip_broadcaster_5": "<b>MẸO:</b> Cảm ơn người xem vì đã điều chỉnh và trả lời những bình luận của họ để duy trì việc tham gia.",
	"ps__tip_broadcaster_6": "<b>MẸO:</b> Nếu bạn mất kết nối trong khi phát, hãy đi đến chỗ nào có tín hiệu tốt hơn.",
	"ps__tip_broadcaster_7": "<b>MẸO:</b> Đề nghị người xem của bạn theo dõi bạn để họ có thể được thông báo khi bạn trực tuyến.",
	"ps__tip_broadcaster_8": "<b>MẸO:</b> Bắt đầu nguồn phát của bạn bằng cách nói xin chào ngay lập tức. Những người xem phát lại của bạn sẽ thích điều này.",
	"ps__tip_broadcaster_9": "<b>MẸO:</b> Cảm ơn người xem của bạn vì đã xem trước khi bạn kết thúc nguồn phát của mình.",
	"ps__tip_pre_broadcast_1": "<b>MẸO:</b> Viết một tiêu đề trước khi bạn bắt đầu nguồn phát của mình và gặp những người có cùng sở thích!",
	"ps__tip_pre_broadcast_2": "<b>MẸO:</b> Một tiêu đề mô tả giúp mọi người hiểu nguồn phát của bạn là về cái gì.",
	"ps__tip_pre_broadcast_3": "<b>MẸO:</b> Bạn cần ý tưởng? Hãy dạo một vòng, chia sẻ tài năng, hoặc nói chuyện về một chủ đề mà bạn thích thú.",
	"ps__tip_pre_broadcast_4": "<b>MẸO:</b> Hãy chắc chắn bạn có tín hiệu điện thoại mạnh trước khi trực tuyến.",
	"ps__tip_pre_broadcast_5": "<b>MẸO:</b> Chia sẻ nguồn phát của bạn trên X để tiếp cận với nhiều đối tượng người xem hơn.",
	"ps__tip_pre_broadcast_6": "<b>MẸO:</b> Nếu bạn theo dõi những người mà theo dõi lại bạn, bạn có thể phát riêng đến họ.",
	"ps__tip_pre_broadcast_8": "<b>MẸO:</b> Thêm một biểu tượng đánh dấu liên quan vào tiêu đề của bạn để giúp mọi người tìm thấy nguồn phát của bạn.",
	"ps__tip_pre_broadcast_9": "<b>MẸO:</b> Đó là tất cả những mẹo mà chúng tôi hiện có, cảm ơn vì đã sử dụng Periscope!",
	"ps__tip_viewer_1": "<b>MẸO:</b> Bạn là một trong những người đầu tiên tham gia, hãy viết một bình luận và nói xin chào!",
	"ps__tip_viewer_2": "<b>MẸO:</b> Viết một bình luận và cho <b>%1$s</b> biết bạn ở đây!",
	"ps__tip_viewer_3": "<b>MẸO:</b> Cho <b>%1$s</b> biết bạn đang xem từ đâu!",
	"ps__tip_viewer_4": "<b>MẸO:</b> Nói xin chào để trò chuyện với <b>%1$s</b> và những người xem khác.",
	"ps__toast_broadcast_notify_followers": "Chúng tôi vừa cho những người theo dõi bạn biết rằng bạn đã tham gia với tư cách khách mời",
