	"tipjar_input_rationale_kakao_pay": "\"Mọi người sẽ gửi tiền tip tới Liên kết QR mà bạn đã nhập ở trên.\nKhi thêm Liên kết QR và chấp nhận tiền tip, bạn có thể tiết lộ thông tin về bản thân được chia sẻ trên dịch vụ thanh toán, bao gồm tên, địa chỉ email và các thông tin khác.\n\n Bạn có thể tìm thấy Liên kết QR KakaoPay tại KakaoTalk Thêm > Trình quét ở trên cùng bên phải > Mã tiền > Biểu tượng hình ảnh khay nhớ tạm. Nhấn vào biểu tượng để sao chép liên kết vào khay nhớ tạm, sau đó dán liên kết ở trên.\"",
